255: static void
256: orc_x86_cpuid_handle_family_model_stepping (void)
257: {
258:   orc_uint32 eax, ebx, ecx, edx;
259:   int family_id;
260:   int model_id;
261:   int ext_family_id;
262:   int ext_model_id;
263: 
264:   orc_x86_cpu_get_cpuid (0x00000001, &eax, &ebx, &ecx, &edx);
265: 
266:   family_id = (eax>>8)&0xf;
267:   model_id = (eax>>4)&0xf;
268:   ext_family_id = (eax>>20)&0xff;
269:   ext_model_id = (eax>>16)&0xf;
270: 
271:   _orc_cpu_family = family_id + ext_family_id;
272:   _orc_cpu_model = (ext_model_id << 4) | model_id;
273:   _orc_cpu_stepping = eax&0xf;
274: 
275:   ORC_INFO ("family_id %d model_id %d stepping %d",
276:       _orc_cpu_family, _orc_cpu_model, _orc_cpu_stepping);
277: }
