287: static void
288: orc_x86_cpu_intel_detect (orc_uint32 level)
289: {
290:   orc_uint32 eax, ebx, ecx, edx;
291: 
292:   if (level >= 1) {
293: 
294:     orc_x86_cpuid_handle_family_model_stepping ();
295: 
296:     orc_x86_cpu_microarchitecture = ORC_X86_UNKNOWN;
297:     if (_orc_cpu_family == 6) {
298:       switch (_orc_cpu_model) {
299:         case 6: /* Mendocino */
300:         case 11: /* Tualatin-256 */
301:           orc_x86_cpu_microarchitecture = ORC_X86_P6;
302:           break;
303:         case 15:
304:         case 22:
305:           orc_x86_cpu_microarchitecture = ORC_X86_CORE;
306:           break;
307:         case 23:
308:         case 29:
309:           orc_x86_cpu_microarchitecture = ORC_X86_PENRYN;
310:           break;
311:         case 26:
312:           orc_x86_cpu_microarchitecture = ORC_X86_NEHALEM;
313:           break;
314:         case 28:
315:           orc_x86_cpu_microarchitecture = ORC_X86_BONNELL;
316:           break;
317:           /* orc_x86_cpu_microarchitecture = ORC_X86_WESTMERE; */
318:           /* orc_x86_cpu_microarchitecture = ORC_X86_SANDY_BRIDGE; */
319:       }
320:     } else if (_orc_cpu_family == 15) {
321:       orc_x86_cpu_microarchitecture = ORC_X86_NETBURST;
322:     }
323:   }
324: 
325:   if (level >= 2) {
326:     orc_x86_cpu_get_cpuid (0x00000002, &eax, &ebx, &ecx, &edx);
327: 
328:     if ((eax&0x80000000) == 0) {
329:       handle_cache_descriptor ((eax>>8)&0xff);
330:       handle_cache_descriptor ((eax>>16)&0xff);
331:       handle_cache_descriptor ((eax>>24)&0xff);
332:     }
333:     if ((ebx&0x80000000) == 0) {
334:       handle_cache_descriptor (ebx&0xff);
335:       handle_cache_descriptor ((ebx>>8)&0xff);
336:       handle_cache_descriptor ((ebx>>16)&0xff);
337:       handle_cache_descriptor ((ebx>>24)&0xff);
338:     }
339:     if ((ecx&0x80000000) == 0) {
340:       handle_cache_descriptor (ecx&0xff);
341:       handle_cache_descriptor ((ecx>>8)&0xff);
342:       handle_cache_descriptor ((ecx>>16)&0xff);
343:       handle_cache_descriptor ((ecx>>24)&0xff);
344:     }
345:     if ((edx&0x80000000) == 0) {
346:       handle_cache_descriptor (edx&0xff);
347:       handle_cache_descriptor ((edx>>8)&0xff);
348:       handle_cache_descriptor ((edx>>16)&0xff);
349:       handle_cache_descriptor ((edx>>24)&0xff);
350:     }
351:   }
352: 
353:   if (level >= 4) {
354:     int i;
355:     for(i=0;i<10;i++){
356:       int type;
357:       int level;
358:       int l;
359:       int p;
360:       int w;
361:       int s;
362: 
363:       get_cpuid_ecx (0x00000004, i, &eax, &ebx, &ecx, &edx);
364:       type = eax&0xf;
365:       if (type == 0) break;
366: 
367:       level = (eax>>5)&0x7;
368:       l = ((ebx>>0)&0xfff)+1;
369:       p = ((ebx>>12)&0x3ff)+1;
370:       w = ((ebx>>22)&0x3ff)+1;
371:       s = ecx + 1;
372: 
373:       ORC_INFO ("type %d level %d line size %d partitions %d ways %d sets %d",
374:           type, level, l, p, w, s);
375:       if (type == 1 || type == 3) {
376:         switch (level) {
377:           case 1:
378:             _orc_data_cache_size_level1 = l*p*w*s;
379:             break;
380:           case 2:
381:             _orc_data_cache_size_level2 = l*p*w*s;
382:             break;
383:           case 3:
384:             _orc_data_cache_size_level3 = l*p*w*s;
385:             break;
386:         }
387:       }
388:     }
389: 
390:   }
391: 
392:   orc_x86_cpu_get_cpuid (0x80000000, &level, &ebx, &ecx, &edx);
393: 
394:   if (level >= 4) {
395:     orc_x86_cpuid_get_branding_string ();
396:   }
397: }
