402:   orc_uint32 eax = 0;
403:   orc_uint32 ebx = 0;
404:   orc_uint32 ecx = 0;
405:   orc_uint32 edx = 0;
406: 
407:   if (level >= 1) {
408:     orc_x86_cpuid_handle_family_model_stepping ();
409: 
410:     orc_x86_cpu_microarchitecture = ORC_X86_UNKNOWN;
411:     switch (_orc_cpu_family) {
412:       case 5:
