442: 
443:     _orc_data_cache_size_level1 = ((ecx>>24)&0xff) * 1024;
444:     ORC_INFO ("L1 D-cache: %d kbytes, %d-way, %d lines/tag, %d line size",
445:         (ecx>>24)&0xff, (ecx>>16)&0xff, (ecx>>8)&0xff, ecx&0xff);
446:     ORC_INFO ("L1 I-cache: %d kbytes, %d-way, %d lines/tag, %d line size",
447:         (edx>>24)&0xff, (edx>>16)&0xff, (edx>>8)&0xff, edx&0xff);
448: 
449:     orc_x86_cpu_get_cpuid (0x80000006, &eax, &ebx, &ecx, &edx);
450:     _orc_data_cache_size_level2 = ((ecx>>16)&0xffff) * 1024;
451:     ORC_INFO ("L2 cache: %d kbytes, %d assoc, %d lines/tag, %d line size",
452:         (ecx>>16)&0xffff, (ecx>>12)&0xf, (ecx>>8)&0xf, ecx&0xff);
453:   }
