456: void
457: orc_x86_cpu_detect (orc_uint32 *level, OrcX86CPUVendor *vendor)
458: {
459:   static OrcX86CPUVendor orc_x86_cpu_vendor = 0;
460:   static orc_uint32 orc_x86_cpu_level = 0;
461:   static int inited = 0;
462:   orc_uint32 ebx = 0;
463:   orc_uint32 edx = 0;
464:   orc_uint32 vendor_id = 0;
465: 
466:   if (inited)
467:     goto done;
468: 
469:   inited = 1;
470: 
471:   orc_x86_cpu_get_cpuid (0x00000000, &orc_x86_cpu_level, &ebx, &vendor_id, &edx);
472: 
473:   ORC_DEBUG("cpuid %d %08x %08x %08x", orc_x86_cpu_level, ebx, edx, vendor_id);
474: 
475: #define ORC_X86_GenuineIntel (('n'<<0)|('t'<<8)|('e'<<16)|('l'<<24))
476: #define ORC_X86_AuthenticAMD (('c'<<0)|('A'<<8)|('M'<<16)|('D'<<24))
477: #define ORC_X86_HygonGenuine (('u'<<0)|('i'<<8)|('n'<<16)|('e'<<24))
478: #define ORC_X86_CentaurHauls (('a'<<0)|('u'<<8)|('l'<<16)|('s'<<24))
479: #define ORC_X86_CyrixInstead (('t'<<0)|('e'<<8)|('a'<<16)|('d'<<24))
480: #define ORC_X86_GenuineTMx86 (('M'<<0)|('x'<<8)|('8'<<16)|('6'<<24))
481: #define ORC_X86_Geode_by_NSC ((' '<<0)|('N'<<8)|('S'<<16)|('6'<<24))
482: #define ORC_X86_NexGenDriven (('i'<<0)|('v'<<8)|('e'<<16)|('n'<<24))
483: #define ORC_X86_RiseRiseRise (('R'<<0)|('i'<<8)|('s'<<16)|('e'<<24))
484: #define ORC_X86_SiS_SiS_SiS_ (('S'<<0)|('i'<<8)|('S'<<16)|(' '<<24))
485: #define ORC_X86_UMC_UMC_UMC_ (('U'<<0)|('M'<<8)|('C'<<16)|(' '<<24))
486: #define ORC_X86_VIA_VIA_VIA_ (('V'<<0)|('I'<<8)|('A'<<16)|(' '<<24))
487: 
488:   switch (vendor_id) {
489:     case ORC_X86_GenuineIntel:
490:       orc_x86_cpu_vendor = ORC_X86_CPU_VENDOR_INTEL;
491:       orc_x86_cpu_intel_detect (orc_x86_cpu_level);
492:       break;
