172:     if (var < ORC_VAR_S1) {
173:       sprintf(s, "ex->dest_ptrs[%d]", var-ORC_VAR_D1);
174:     } else {
175:       sprintf(s, "ex->src_ptrs[%d]", var-ORC_VAR_S1);
176:     }
177:   } else {
178:     sprintf(s, "ex->arrays[%d]", var);
179:   }
180: }
