195: static void
196: orc_compiler_c_assemble (OrcCompiler *compiler)
197: {
198:   int i;
199:   int j;
200:   OrcInstruction *insn;
201:   OrcStaticOpcode *opcode;
202:   OrcRule *rule;
203:   int prefix = 0;
204: 
205:   if (!(compiler->target_flags & ORC_TARGET_C_BARE)) {
206:     ORC_ASM_CODE(compiler,"void\n");
207:     ORC_ASM_CODE(compiler,"%s (OrcExecutor *ex)\n", compiler->program->name);
208:     ORC_ASM_CODE(compiler,"{\n");
209:   }
210: 
211:   ORC_ASM_CODE(compiler,"%*s  int i;\n", prefix, "");
212:   if (compiler->program->is_2d) {
213:     ORC_ASM_CODE(compiler,"  int j;\n");
214:   }
215:   if (compiler->program->constant_n == 0) {
216:     if (!(compiler->target_flags & ORC_TARGET_C_NOEXEC) &&
217:         !(compiler->target_flags & ORC_TARGET_C_OPCODE)) {
218:       ORC_ASM_CODE(compiler,"  int n = ex->n;\n");
219:     }
220:   } else {
221:     ORC_ASM_CODE(compiler,"  int n = %d;\n", compiler->program->constant_n);
222:   }
223:   if (compiler->program->is_2d) {
224:     if (compiler->program->constant_m == 0) {
225:       if (!(compiler->target_flags & ORC_TARGET_C_NOEXEC)) {
226:         ORC_ASM_CODE(compiler,"  int m = ex->params[ORC_VAR_A1];\n");
227:       }
228:     } else {
229:       ORC_ASM_CODE(compiler,"  int m = %d;\n", compiler->program->constant_m);
230:     }
231:   }
232: 
233:   for(i=0;i<ORC_N_COMPILER_VARIABLES;i++){
234:     OrcVariable *var = compiler->vars + i;
235:     if (var->name == NULL) continue;
236:     switch (var->vartype) {
237:       case ORC_VAR_TYPE_CONST:
238:         break;
239:       case ORC_VAR_TYPE_TEMP:
240:         if (!(var->last_use == -1 && var->first_use == 0)) {
241:           if (var->flags & ORC_VAR_FLAG_VOLATILE_WORKAROUND) {
242:             ORC_ASM_CODE(compiler,"#if defined(__APPLE__) && __GNUC__ == 4 && __GNUC_MINOR__ == 2 && defined (__i386__) \n");
243:             ORC_ASM_CODE(compiler,"  volatile %s var%d;\n",
244:                 c_get_type_name(var->size), i);
245:             ORC_ASM_CODE(compiler,"#else\n");
246:             ORC_ASM_CODE(compiler,"  %s var%d;\n",
247:                 c_get_type_name(var->size), i);
248:             ORC_ASM_CODE(compiler,"#endif\n");
249:           } else {
250:             ORC_ASM_CODE(compiler,"  %s var%d;\n",
251:                 c_get_type_name(var->size), i);
252:           }
253:         }
254:         break;
255:       case ORC_VAR_TYPE_SRC:
256:         ORC_ASM_CODE(compiler,"  const %s * ORC_RESTRICT ptr%d;\n",
257:             c_get_type_name (var->size),
258:             i);
259:         break;
260:       case ORC_VAR_TYPE_DEST:
261:         ORC_ASM_CODE(compiler,"  %s * ORC_RESTRICT ptr%d;\n",
262:             c_get_type_name (var->size),
263:             i);
264:         break;
265:       case ORC_VAR_TYPE_ACCUMULATOR:
266:         if (var->size >= 2) {
267:           ORC_ASM_CODE(compiler,"  %s var%d =  { 0 };\n",
268:               c_get_type_name (var->size),
269:               i);
270:         } else {
271:           ORC_ASM_CODE(compiler,"  %s var%d = 0;\n",
272:               c_get_type_name (var->size),
273:               i);
274:         }
275:         break;
276:       case ORC_VAR_TYPE_PARAM:
277:         break;
278:       default:
279:         ORC_COMPILER_ERROR(compiler, "bad vartype");
280:         break;
281:     }
282:   }
283: 
284:   ORC_ASM_CODE(compiler,"\n");
285:   if (compiler->program->is_2d) {
286:     ORC_ASM_CODE(compiler,"  for (j = 0; j < m; j++) {\n");
287:     prefix = 2;
288: 
289:     for(i=0;i<ORC_N_COMPILER_VARIABLES;i++){
290:       OrcVariable *var = compiler->vars + i;
291:       if (var->name == NULL) continue;
292:       switch (var->vartype) {
293:         case ORC_VAR_TYPE_SRC:
294:           {
295:             char s1[40], s2[40];
296:             get_varname(s1, compiler, i);
297:             get_varname_stride(s2, compiler, i);
298:             ORC_ASM_CODE(compiler,
299:                 "    ptr%d = ORC_PTR_OFFSET(%s, %s * j);\n",
300:                 i, s1, s2);
301:           }
302:           break;
303:         case ORC_VAR_TYPE_DEST:
304:           {
305:             char s1[40], s2[40];
306:             get_varname(s1, compiler, i),
307:             get_varname_stride(s2, compiler, i),
308:             ORC_ASM_CODE(compiler,
309:                 "    ptr%d = ORC_PTR_OFFSET(%s, %s * j);\n",
310:                 i, s1, s2);
311:           }
312:           break;
313:         default:
314:           break;
315:       }
316:     }
317:   } else {
318:     for(i=0;i<ORC_N_COMPILER_VARIABLES;i++){
319:       OrcVariable *var = compiler->vars + i;
320:       char s[40];
321:       if (var->name == NULL) continue;
322:       get_varname(s, compiler, i);
323:       switch (var->vartype) {
324:         case ORC_VAR_TYPE_SRC:
325:           ORC_ASM_CODE(compiler,"  ptr%d = (%s *)%s;\n", i,
326:               c_get_type_name (var->size), s);
327:           break;
328:         case ORC_VAR_TYPE_DEST:
329:           ORC_ASM_CODE(compiler,"  ptr%d = (%s *)%s;\n", i,
330:               c_get_type_name (var->size), s);
331:           break;
332:         default:
333:           break;
334:       }
335:     }
336:   }
337: 
338:   ORC_ASM_CODE(compiler,"\n");
339:   for(j=0;j<compiler->n_insns;j++){
340:     insn = compiler->insns + j;
341:     opcode = insn->opcode;
342: 
343:     if (!(insn->flags & ORC_INSN_FLAG_INVARIANT)) continue;
344: 
345:     ORC_ASM_CODE(compiler,"%*s    /* %d: %s */\n", prefix, "",
346:         j, insn->opcode->name);
347: 
348:     rule = insn->rule;
349:     if (!rule) {
350:       ORC_COMPILER_ERROR(compiler, "No rule for: %s on target %s", opcode->name,
351:           compiler->target->name);
352:       continue;
353:     }
354:     ORC_ASM_CODE(compiler,"%*s", prefix, "");
355:     if (insn->flags & (ORC_INSTRUCTION_FLAG_X2|ORC_INSTRUCTION_FLAG_X4)) {
356:       int n;
357:       if (insn->flags & ORC_INSTRUCTION_FLAG_X2) {
358:         n = 2;
359:       } else {
360:         n = 4;
361:       }
362:       for(i=0;i<n;i++){
363:         compiler->unroll_index = i;
364:         ORC_ASM_CODE(compiler,"%*s", prefix, "");
365:         rule->emit (compiler, rule->emit_user, insn);
366:       }
367:     } else {
368:       ORC_ASM_CODE(compiler,"%*s", prefix, "");
369:       rule->emit (compiler, rule->emit_user, insn);
370:     }
371:   }
372: 
373:   ORC_ASM_CODE(compiler,"\n");
374:   ORC_ASM_CODE(compiler,"%*s  for (i = 0; i < n; i++) {\n", prefix, "");
375: 
376:   /* Emit instructions */
377:   for(j=0;j<compiler->n_insns;j++){
378:     insn = compiler->insns + j;
379:     opcode = insn->opcode;
380: 
381:     if (insn->flags & ORC_INSN_FLAG_INVARIANT) continue;
382: 
383:     ORC_ASM_CODE(compiler,"%*s    /* %d: %s */\n", prefix, "",
384:         j, insn->opcode->name);
385: 
386:     rule = insn->rule;
387:     if (!rule) {
388:       ORC_COMPILER_ERROR(compiler, "No rule for: %s on target %s", opcode->name,
389:           compiler->target->name);
390:       continue;
391:     }
392: 
393:     if (insn->flags & (ORC_INSTRUCTION_FLAG_X2|ORC_INSTRUCTION_FLAG_X4)) {
394:       int n;
395:       if (insn->flags & ORC_INSTRUCTION_FLAG_X2) {
396:         n = 2;
397:       } else {
398:         n = 4;
399:       }
400:       for(i=0;i<n;i++){
401:         compiler->unroll_index = i;
402:         ORC_ASM_CODE(compiler,"%*s", prefix, "");
403:         rule->emit (compiler, rule->emit_user, insn);
404:       }
405:     } else {
406:       ORC_ASM_CODE(compiler,"%*s", prefix, "");
407:       rule->emit (compiler, rule->emit_user, insn);
408:     }
409:   }
410:   ORC_ASM_CODE(compiler,"%*s  }\n", prefix, "");
411:   if (compiler->program->is_2d) {
412:     ORC_ASM_CODE(compiler,"  }\n");
413:   }
414: 
415:   for(i=0;i<ORC_N_COMPILER_VARIABLES;i++){
416:     char varname[40];
417:     OrcVariable *var = compiler->vars + i;
418:     if (var->name == NULL) continue;
419:     switch (var->vartype) {
420:       case ORC_VAR_TYPE_ACCUMULATOR:
421:         c_get_name_int (varname, compiler, NULL, i);
422:         if (var->size == 2) {
423:           if (compiler->target_flags & ORC_TARGET_C_NOEXEC) {
424:             ORC_ASM_CODE(compiler,"  *%s = (%s & 0xffff);\n",
425:                 orc_variable_id_get_name (i), varname);
426:           } else if (compiler->target_flags & ORC_TARGET_C_OPCODE) {
427:             ORC_ASM_CODE(compiler,"  ((orc_union32 *)ex->dest_ptrs[%d])->i = "
428:                 "(%s + ((orc_union32 *)ex->dest_ptrs[%d])->i) & 0xffff;\n",
429:                 i - ORC_VAR_A1, varname, i - ORC_VAR_A1);
430:           } else {
431:             ORC_ASM_CODE(compiler,"  ex->accumulators[%d] = (%s & 0xffff);\n",
432:                 i - ORC_VAR_A1, varname);
433:           }
434:         } else {
435:           if (compiler->target_flags & ORC_TARGET_C_NOEXEC) {
436:             ORC_ASM_CODE(compiler,"  *%s = %s;\n",
437:                 orc_variable_id_get_name (i), varname);
438:           } else if (compiler->target_flags & ORC_TARGET_C_OPCODE) {
439:             ORC_ASM_CODE(compiler,"  ((orc_union32 *)ex->dest_ptrs[%d])->i += (orc_uint%d)%s;\n",
440:                 i - ORC_VAR_A1, var->size * 8, varname);
441:           } else {
442:             ORC_ASM_CODE(compiler,"  ex->accumulators[%d] = %s;\n",
443:                 i - ORC_VAR_A1, varname);
444:           }
445:         }
446:         break;
447:       default:
448:         break;
449:     }
450:   }
451: 
452:   if (!(compiler->target_flags & ORC_TARGET_C_BARE)) {
453:     ORC_ASM_CODE(compiler,"}\n");
454:     ORC_ASM_CODE(compiler,"\n");
455:   }
456: }
