461: static void
462: c_get_name_int (char *name, OrcCompiler *p, OrcInstruction *insn, int var)
463: {
464:   if (p->vars[var].vartype == ORC_VAR_TYPE_PARAM) {
465:     if (p->target_flags & ORC_TARGET_C_NOEXEC) {
466:       sprintf(name,"%s", orc_variable_id_get_name (var));
467:     } else if (p->target_flags & ORC_TARGET_C_OPCODE) {
468:       sprintf(name,"((orc_union64 *)(ex->src_ptrs[%d]))->i",
469:           var - ORC_VAR_P1 + p->program->n_src_vars);
470:     } else {
471:       switch (p->vars[var].param_type) {
472:         case ORC_PARAM_TYPE_INT:
473:           sprintf(name,"ex->params[%d]", var);
474:           break;
475:         case ORC_PARAM_TYPE_FLOAT:
476:           sprintf(name,"((orc_union32 *)(ex->params+%d))->i", var);
477:           break;
478:         case ORC_PARAM_TYPE_INT64:
479:           /* FIXME */
480:           sprintf(name,"((orc_union32 *)(ex->params+%d))->i", var);
481:           break;
482:         case ORC_PARAM_TYPE_DOUBLE:
483:           /* FIXME */
484:           sprintf(name,"((orc_union32 *)(ex->params+%d))->i", var);
485:           break;
486:         default:
487:           ORC_ASSERT(0);
488:       }
489:     }
490:   } else if (p->vars[var].vartype == ORC_VAR_TYPE_CONST) {
491:     if (p->vars[var].value.i == 0x80000000) {
492:       sprintf(name,"0x80000000");
493:     } else {
494:       if (p->vars[var].value.i == (int)p->vars[var].value.i) {
495:         sprintf(name, "%d", (int)p->vars[var].value.i);
496:       } else {
497:         ORC_ASSERT(0);
498:       }
499:     }
500:   } else {
501:     if (p->vars[var].size >= 2) {
502:       if (insn && (insn->flags & ORC_INSTRUCTION_FLAG_X2)) {
503:         sprintf(name, "var%d.x2[%d]", var, p->unroll_index);
504:       } else if (insn && (insn->flags & ORC_INSTRUCTION_FLAG_X4)) {
505:         sprintf(name, "var%d.x4[%d]", var, p->unroll_index);
506:       } else {
507:         sprintf(name, "var%d.i", var);
508:       }
509:     } else {
510:       sprintf(name, "var%d", var);
511:     }
512:   }
513: }
