515: static void
516: c_get_const_var_literal (OrcCompiler *p, const OrcVariable *var, char lit[40])
517: {
518:   orc_uint32 v32 = var->value.i;
519:   orc_uint64 v64 = var->value.i;
520:   switch (var->size) {
521:       case 1: snprintf (lit, 40, "0x%02x", v32 & 0xFF); break;
522:       case 2: snprintf (lit, 40, "0x%04x", v32 & 0xFFFF); break;
523:       case 4: snprintf (lit, 40, "0x%08x", v32); break;
524:       case 8:
525:         snprintf (lit, 40, "ORC_UINT64_C(0x%08x%08x)",
526:             (orc_uint32)(v64 >> 32), v32); // %llx is not available everywhere
527:         break;
528:       default:
529:         ORC_COMPILER_ERROR(p, "Variable size %d not supported", var->size);
530:         break;
531:   }
532: }
