534: static void
535: c_get_name_float (char *name, OrcCompiler *p, OrcInstruction *insn, int var)
536: {
537:   if (insn && (insn->flags & ORC_INSTRUCTION_FLAG_X2)) {
538:     sprintf(name, "var%d.x2f[%d]", var, p->unroll_index);
539:   } else if (insn && (insn->flags & ORC_INSTRUCTION_FLAG_X4)) {
540:     sprintf(name, "var%d.x4f[%d]", var, p->unroll_index);
541:   } else {
542:     switch (p->vars[var].vartype) {
543:       case ORC_VAR_TYPE_CONST:
544:       case ORC_VAR_TYPE_TEMP:
545:       case ORC_VAR_TYPE_ACCUMULATOR:
546:       case ORC_VAR_TYPE_SRC:
547:       case ORC_VAR_TYPE_DEST:
548:         sprintf(name, "var%d.f", var);
549:         break;
550:       case ORC_VAR_TYPE_PARAM:
551:         sprintf(name, "var%d", var);
552:         break;
553:       default:
554:         ORC_COMPILER_ERROR(p, "bad vartype");
555:         sprintf(name, "ERROR");
556:         break;
557:     }
558:   }
559: }
