807: static void
808: c_rule_loadpX (OrcCompiler *p, void *user, OrcInstruction *insn)
809: {
810:   char dest[40];
811:   int size = ORC_PTR_TO_INT(user);
812: 
813:   if ((p->target_flags & ORC_TARGET_C_NOEXEC) &&
814:       (p->vars[insn->src_args[0]].param_type == ORC_PARAM_TYPE_FLOAT ||
815:        p->vars[insn->src_args[0]].param_type == ORC_PARAM_TYPE_DOUBLE))
816:     c_get_name_float (dest, p, insn, insn->dest_args[0]);
817:   else
818:     c_get_name_int (dest, p, insn, insn->dest_args[0]);
819: 
820:   if (p->vars[insn->src_args[0]].vartype == ORC_VAR_TYPE_PARAM) {
821:     if (p->target_flags & ORC_TARGET_C_NOEXEC) {
822:       ORC_ASM_CODE(p,"    %s = %s;\n", dest, orc_variable_id_get_name (insn->src_args[0]));
823:     } else if (p->target_flags & ORC_TARGET_C_OPCODE) {
824:       ORC_ASM_CODE(p,"    %s = ((orc_union64 *)(ex->src_ptrs[%d]))->i;\n",
825:           dest, insn->src_args[0] - ORC_VAR_P1 + p->program->n_src_vars);
826:     } else {
827:       if (size == 8) {
828:         ORC_ASM_CODE(p,"    %s = (ex->params[%d] & 0xffffffff) | ((orc_uint64)(ex->params[%d + (ORC_N_PARAMS)]) << 32);\n",
829:             dest, insn->src_args[0], insn->src_args[0]);
830:       } else {
831:         ORC_ASM_CODE(p,"    %s = ex->params[%d];\n", dest,
832:             insn->src_args[0]);
833:       }
834:     }
835:   } else if (p->vars[insn->src_args[0]].vartype == ORC_VAR_TYPE_CONST) {
836:     char lit[40];
837:     const OrcVariable *src = &p->vars[insn->src_args[0]];
838:     c_get_const_var_literal (p, src, lit);
839:     ORC_ASM_CODE(p,"    %s = %s; /* %d or %gf */\n",
840:         dest, lit, (int)src->value.i, src->value.f);
841:   } else {
842:     ORC_COMPILER_ERROR(p, "expected param or constant");
843:   }
844: }
